DELIMITER $$
CREATE TRIGGER `marks_audit_trail_delete_marks` AFTER DELETE ON `marks` FOR EACH ROW BEGIN
    centre_code,
    exam_no,
    subject_code,
    paper_no,
     old_mark,
    new_mark,
    status,
    sen,
    improvised_mark,
    entered_by,
    action,
    date_entered,
    marking_centre
  ) VALUES (
    OLD.centre_code,
    OLD.exam_no,
    OLD.subject_code,
    OLD.paper_no,
     "",
    OLD.mark,
    OLD.status,
    OLD.sen,
    OLD.improvised_mark,
    OLD.entered_by,
    'DELETE',
    NOW(),  -- You may need to adjust this based on your specific database's date/time functions
    OLD.marking_centre
  );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `marks_audit_trail_trigger` AFTER UPDATE ON `marks` FOR EACH ROW BEGIN
  IF (NEW.mark != OLD.mark OR OLD.status != NEW.status) AND (OLD.status !="L") AND (OLD.disable != 1) THEN
      centre_code,
      exam_no,
      subject_code,
      paper_no,
      old_mark,
        old_status,
      new_mark,
      status,
      sen,
      improvised_mark,
      entered_by,
      action,
      date_entered,
      marking_centre
    ) VALUES (
      NEW.centre_code,
      NEW.exam_no,
      NEW.subject_code,
      NEW.paper_no,
      CASE WHEN OLD.mark = 0 AND OLD.status ="L" THEN "" ELSE OLD.mark END,
        OLD.status,
      NEW.mark,
      NEW.status,
      NEW.sen,
      NEW.improvised_mark,
      NEW.entered_by,
      'UPDATE',
      NEW.date_entered,  -- You may need to adjust this based on your specific database's date/time functions
      NEW.marking_centre  
    );
  END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `marks_audit_trail_trigger_insert_improvised` AFTER INSERT ON `marks` FOR EACH ROW BEGIN
IF NEW.status != "L" AND NEW.improvised_mark != 0 THEN
    centre_code,
    exam_no,
    subject_code,
    paper_no,
    old_mark,
    new_mark,
    status,
    sen,
    improvised_mark,
    entered_by,
    action,
    date_entered,
