  ) VALUES (
    NEW.centre_code,
    NEW.exam_no,
    NEW.subject_code,
    NEW.paper_no,
    "",
    NEW.mark,
    NEW.status,
    NEW.sen,
    NEW.improvised_mark,
    NEW.entered_by,
    'INSERT',
    NOW(), 
    NEW.marking_centre
  );
  END IF;
END
$$
